import{_ as r,D as o,c as l,I as t,j as e,a as s,a4 as i,o as h}from"./chunks/framework.CRCV4hx_.js";const S=JSON.parse('{"title":"Checkout","description":"","frontmatter":{},"headers":[],"relativePath":"checkout.md","filePath":"checkout.md"}'),c={name:"checkout.md"},d=i('<h1 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h1><p>The <code>Checkout</code> component handles the whole checkout process: it allows the user to select extras or options, lets them add a coupon for a discount, gets the user&#39;s personal details, and handles the payment.</p><p>In v6 the checkout supports <strong>multiple payment gateways</strong>. When more than one gateway is enabled, the user is shown a payment-method picker before paying; with a single gateway it is auto-selected, and when the price is zero the payment step is skipped entirely.</p><p>In this page, we&#39;ll go over the setup required for the <code>Checkout</code> component to function correctly and how to customize it to fit your needs.</p><h2 id="component-basics" tabindex="-1">Component basics <a class="header-anchor" href="#component-basics" aria-label="Permalink to &quot;Component basics&quot;">​</a></h2><p>Before using this component, let&#39;s go through the required steps to get it working:</p><ol><li>You need to create an Entry that will be used as the checkout page. This Entry can follow your website&#39;s design but must have a different template that will include the <code>Checkout</code> component.</li><li>You also need to create a &quot;Checkout complete&quot; page. Again, this page can be like any page on your site, but in its template, you must include the <code>resrv_checkout_redirect</code> tag.</li><li>You need to create the checkout form. If you used the installer, a sample checkout form is already published for you to edit.</li><li>You must configure and enable at least one payment gateway in order to accept payments. See the <a href="./payment-gateways">Payment gateways</a> overview, plus the <a href="./stripe">Stripe</a> and <a href="./mollie">Mollie</a> pages.</li></ol><h2 id="checkout-component" tabindex="-1">Checkout Component <a class="header-anchor" href="#checkout-component" aria-label="Permalink to &quot;Checkout Component&quot;">​</a></h2><p>To load the Checkout component, first create a new Entry in your default collection (for example &quot;Pages&quot;). Create a custom template for this page and include the <code>Checkout</code> component:</p><div class="language-antlers vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">antlers</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">livewire</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">checkout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>As simple as that! The component has a few properties that you can set to customize it to your needs:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>enableExtrasStep</td><td>boolean</td><td>true</td><td>By default the component starts with a step that allows the user to select Extras / Options. If you don&#39;t use them, you can disable it by setting this to false and the step is skipped.</td></tr><tr><td>enableCoupon</td><td>boolean</td><td>true</td><td>By default the component allows the user to add a discount coupon, you can disable this here if you don&#39;t use them. In v6 this is locked: it is set once when the component mounts and can no longer be toggled client-side.</td></tr><tr><td>view</td><td>string</td><td>&quot;checkout&quot;</td><td>You can override the view that is used to render the component. Expects a <code>name.blade.php</code> file in the <code>/resources/views/vendor/statamic-resrv/livewire</code> folder.</td></tr></tbody></table><p>You set these as attributes on the tag (note the snake_case casing):</p><div class="language-antlers vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">antlers</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">livewire</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">checkout</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> enable_extras_step</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;false&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> enable_coupon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;false&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> view</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-checkout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div>',14),p=i('<h2 id="checkout-steps" tabindex="-1">Checkout steps <a class="header-anchor" href="#checkout-steps" aria-label="Permalink to &quot;Checkout steps&quot;">​</a></h2><p>The checkout is organized into three internal steps:</p><ol><li><strong>Extras &amp; options</strong>: The user picks any <a href="./extras">Extras</a> and <a href="./options">Options</a> for the reservation. This step is skipped when <code>enableExtrasStep</code> is <code>false</code> (any extras or options already stored in the session are still applied).</li><li><strong>Personal details</strong>: The user fills in the checkout form with their details. The submit button reads <em>&quot;Continue to payment&quot;</em>, or <em>&quot;Confirm reservation&quot;</em> when the amount due is zero.</li><li><strong>Payment</strong>: What renders here depends on how many gateways are available: <ul><li><strong>More than one gateway</strong> → a payment-method picker is shown first (see below).</li><li><strong>Exactly one gateway</strong> → it is auto-selected and the payment view is shown directly.</li><li><strong>Zero price</strong> → the whole payment step is skipped and the reservation is confirmed (see <a href="#skip-payment">Skip Payment</a>).</li></ul></li></ol><p>The step indicator adjusts automatically: the <em>Extras &amp; options</em> row is hidden when <code>enableExtrasStep</code> is <code>false</code>, and the <em>Payment</em> row is hidden entirely for zero-price reservations.</p><h2 id="selecting-a-payment-method" tabindex="-1">Selecting a payment method <a class="header-anchor" href="#selecting-a-payment-method" aria-label="Permalink to &quot;Selecting a payment method&quot;">​</a></h2><p>When more than one payment gateway is enabled and survives the amount filtering for the reservation total, the user is shown a <strong>Select payment method</strong> picker before they pay. Each option displays the gateway label, and if a surcharge is configured for that gateway, a suffix is appended:</p><ul><li>Percentage surcharge: <code>(+10% surcharge)</code></li><li>Fixed surcharge: <code>(+€ 5 surcharge)</code></li></ul><p>When the user selects a gateway, the surcharge is added to the amount, a payment intent is created, and the matching payment view is rendered (or, for redirect gateways such as Mollie, the user is sent to the gateway and back).</p>',8),u=i(`<p>A few behaviours to keep in mind:</p><ul><li><strong>Single gateway:</strong> the picker is never shown; the only available gateway is selected automatically.</li><li><strong>No gateway for the amount:</strong> if no enabled gateway accepts the reservation amount (for example, every gateway has a minimum/maximum limit that excludes it), the user stays on the details step and an error is shown. Make sure your gateway amount limits cover the totals you expect.</li></ul><p>See <a href="./payment-gateways">Payment gateways</a> for how to enable gateways and configure surcharges and amount limits.</p><h2 id="offline-pay-later" tabindex="-1">Offline / pay-later <a class="header-anchor" href="#offline-pay-later" aria-label="Permalink to &quot;Offline / pay-later&quot;">​</a></h2><p>Resrv ships with an <strong>Offline</strong> gateway (<code>OfflinePaymentGateway</code>) for bookings you collect payment for manually: bank transfer, pay on arrival, and so on. Enable it like any other gateway (see <a href="./payment-gateways">Payment gateways</a>).</p><p>When the user reaches the offline gateway, they see the amount due and a <strong>Confirm reservation</strong> button instead of a card form. Clicking it confirms the booking server-side without taking a real payment. If more than one gateway is available, a <em>Change payment method</em> button lets the user go back to the picker.</p><p>Because no real payment is captured, the customer is redirected to the checkout-complete page with the <em>pending</em> status (see below): a message telling them the booking has been received and payment is still to be settled. The reservation itself is already confirmed server-side (availability is secured and the confirmation email is sent); you simply collect and record the payment outside Resrv.</p><h2 id="checkout-complete" tabindex="-1">Checkout Complete <a class="header-anchor" href="#checkout-complete" aria-label="Permalink to &quot;Checkout Complete&quot;">​</a></h2><p>After the checkout is complete, the user is redirected to the &quot;Checkout complete&quot; page. This page can be like any page of your site, but in its template you must include the <code>resrv_checkout_redirect</code> tag:</p><div class="language-antlers vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">antlers</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">resrv_checkout_redirect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;w-full&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text-xl xl:text-2xl font-bold mb-3 lg:mb-4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            {{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lg:text-lg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            {{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">/resrv_checkout_redirect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>The tag is gateway-aware: it resolves the gateway from the current reservation (or from the <code>resrv_gateway</code> query parameter that redirect gateways append on the way back) and asks it how the payment went. It exposes the following variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td>One of <code>success</code>, <code>failed</code>, or <code>pending</code>.</td></tr><tr><td><code>title</code></td><td>A localized title for the result.</td></tr><tr><td><code>message</code></td><td>A localized message for the result.</td></tr><tr><td><code>reservation</code></td><td>The reservation data array.</td></tr></tbody></table><p>The three statuses are:</p><ul><li><strong><code>success</code></strong>: <em>&quot;Payment successful.&quot;</em> The payment was processed and the reservation is confirmed.</li><li><strong><code>failed</code></strong>: <em>&quot;Payment failed.&quot;</em> The payment was not successful; the customer is asked to retry or get in touch.</li><li><strong><code>pending</code></strong>: <em>&quot;Reservation received.&quot;</em> The reservation has been received and held, and will be confirmed once payment is settled. This is what offline / pay-later bookings and other held bookings return.</li></ul><p>Inside the tag you can access the <code>reservation</code> variable that contains the reservation data. This is the correct place to add any goal-based events, like Analytics.</p><h2 id="choosing-the-checkout-form" tabindex="-1">Choosing the checkout form <a class="header-anchor" href="#choosing-the-checkout-form" aria-label="Permalink to &quot;Choosing the checkout form&quot;">​</a></h2><p>The checkout form used at step 2 is resolved per reservation, so different collections or entries can use different forms. Resrv picks the first matching form in this precedence order:</p><ol><li><strong>Entry mapping</strong>: a form mapped to that specific entry.</li><li><strong>Legacy <code>resrv_override_form</code></strong>: the per-entry field from v5, kept for backwards compatibility.</li><li><strong>Collection mapping</strong>: a form mapped to the entry&#39;s collection.</li><li><strong>Default form</strong>: the global default checkout form.</li></ol><p>You configure the default form and the optional collection / entry mappings in <strong>Resrv → Settings → Checkout</strong> (<code>checkout_forms_default</code>, <code>checkout_forms_collections</code>, <code>checkout_forms_entries</code>). Developers who prefer to keep these mappings under version control can instead set the nested <code>checkout_forms</code> array (<code>default</code> / <code>collections</code> / <code>entries</code>) in <code>config/resrv-config.php</code>, which takes precedence over the Control Panel keys when present.</p><p>See the <a href="./configuration">Configuration</a> page for the full list of settings.</p><h2 id="checkout-form" tabindex="-1">Checkout form <a class="header-anchor" href="#checkout-form" aria-label="Permalink to &quot;Checkout form&quot;">​</a></h2><p>We are leveraging the <a href="https://statamic.dev/forms" target="_blank" rel="noreferrer">Statamic form builder</a> in order to allow you to customize the checkout form. If you published it during the installation process, you will find it in your Blueprints.</p><div class="warning custom-block"><p class="custom-block-title">ALWAYS KEEP THE EMAIL FIELD</p><p>The email field (with the handle <code>email</code>) is required for the checkout emails to work. Always make sure to keep it in your checkout form.</p></div><p>You can use Statamic&#39;s validation tab to add validation to your fields. The fields that are implemented in the frontend are:</p>`,24),k=e("li",null,"Text",-1),m=e("li",null,"Radio",-1),g=e("li",null,"Checkboxes",-1),y=e("li",null,"Select",-1),f=e("li",null,"Textarea",-1),E=e("li",null,"Integer",-1),b=e("li",null,"Toggle",-1),w=e("p",null,[s("The dictionary "),e("em",null,"Countries"),s(" will display an AlpineJS filtered select box. Resrv adds the dictionary "),e("em",null,"Country Phone Codes"),s(" which displays a select box with all country codes plus an input box for the actual phone number.")],-1),v=i('<h2 id="cancellation-policy" tabindex="-1">Cancellation policy <a class="header-anchor" href="#cancellation-policy" aria-label="Permalink to &quot;Cancellation policy&quot;">​</a></h2><p>When a <a href="./rates">rate</a> declares a cancellation policy, a <em>Cancellation policy</em> label is shown in the checkout sidebar (for example <em>&quot;Free cancellation until Mon 03 Jun 2026&quot;</em> or <em>&quot;Non-refundable&quot;</em>). The label is snapshotted onto the reservation at booking time, so later changes to the rate never alter the terms an existing booking was made under.</p><p><strong>Non-refundable bookings are always charged in full</strong> at checkout, even after a coupon is applied or removed, regardless of the global free-cancellation settings.</p><h2 id="required-configuration" tabindex="-1">Required Configuration <a class="header-anchor" href="#required-configuration" aria-label="Permalink to &quot;Required Configuration&quot;">​</a></h2><p>For the checkout to work correctly, you need to select the Checkout Entry, the Checkout Complete Entry, and the default Checkout form in the addon&#39;s <a href="./configuration">configuration</a> page.</p><p>Finally, you must also set up and enable at least one <a href="./payment-gateways">payment gateway</a>.</p><h2 id="skip-payment" tabindex="-1">Skip Payment <a class="header-anchor" href="#skip-payment" aria-label="Permalink to &quot;Skip Payment&quot;">​</a></h2><p>If the price of the reservation is zero (either because you set the price to zero, or because dynamic pricing brings it to zero), the checkout is completed without any payment. The payment step is never shown, the <em>Payment</em> row is hidden from the step indicator, and the step-2 button reads <em>&quot;Confirm reservation&quot;</em>. This means you can use only the reservation part of Resrv. For example, if you have a restaurant that takes reservations but doesn&#39;t charge for them, you can simply set the price to zero.</p><p>This is distinct from the <strong>offline / pay-later</strong> gateway (a real gateway that confirms the booking immediately but shows the customer a &quot;payment pending&quot; message) and from the affiliate &quot;pay later&quot; flow used by partners: both of those still go through step 2 with a non-zero amount.</p>',9);function _(C,q,T,x,F,A){const a=o("Image"),n=o("Badge");return h(),l("div",null,[d,t(a,{src:"./img/resrv-checkout.webp",alt:"The checkout component."}),p,t(a,{src:"./img/resrv-checkout-gateway-picker.webp",alt:"The checkout payment method picker with multiple gateways."}),u,e("ul",null,[k,m,g,y,f,E,b,e("li",null,[s("Dictionaries "),t(n,{type:"tip",text:"NEW"})])]),w,t(a,{src:"./img/resrv-checkout-form.webp",alt:"The checkout form in the Statamic form builder."}),t(a,{src:"./img/resrv-checkout-form-frontend.webp",alt:"And the same checkout form in the frontend."}),v])}const B=r(c,[["render",_]]);export{S as __pageData,B as default};
